import type pg from "pg";
import type { AppConfig } from "../lib/config";
import type { Clock } from "../lib/clock";
import { log } from "../lib/log";
import { detectInjection } from "../lib/enrich/inject-detect";
import { createProviders } from "../lib/providers";
import { claimJobs, releaseUnchanged } from "./claim";
import { CircuitBreaker } from "./breaker";
import {
  ensureBudgetDay,
  reserveBudget,
  releaseBudget,
  dollarsToMicro,
  estimateCostMicro,
} from "./budget";
import { finishSentiment, finishSummaryTopics, hashInput } from "./finish";
import { classifyProviderError } from "./classify";
import { maxAttemptsFor, nextDelayMs } from "./retry";
import { sweepExpired } from "./sweeper";

export async function runWorkerLoop(opts: {
  pool: pg.Pool;
  config: AppConfig;
  clock: Clock;
  shouldStop: () => boolean;
}): Promise<void> {
  const { pool, config, clock, shouldStop } = opts;
  const workerId = `worker-${process.pid}`;
  const providers = createProviders(config);
  const breakers = {
    jev: new CircuitBreaker("jev"),
    openai: new CircuitBreaker("openai"),
  };

  while (!shouldStop()) {
    // Kill switch
    const flag = await pool.query<{ value: string }>(
      `SELECT value FROM system_flags WHERE key = 'enrichment_enabled'`,
    );
    if (flag.rows[0]?.value === "false") {
      await clock.sleep(2000);
      continue;
    }

    await sweepExpired(pool);

    for (const part of ["sentiment", "summary_topics"] as const) {
      if (shouldStop()) break;
      const breaker = part === "sentiment" ? breakers.jev : breakers.openai;
      const now = clock.now().getTime();
      if (!breaker.canRequest(now)) {
        await pool.query(`SELECT worker_set_flag($1, $2)`, [
          `breaker.${breaker.name}`,
          breaker.snapshot(),
        ]);
        continue;
      }

      const client = await pool.connect();
      try {
        await client.query("BEGIN");
        const jobs = await claimJobs(client, part, workerId, 1);
        if (jobs.length === 0) {
          await client.query("COMMIT");
          continue;
        }
        // If breaker opened between check and claim, release without consuming attempt
        if (!breaker.canRequest(clock.now().getTime())) {
          for (const j of jobs) await releaseUnchanged(client, j.id, workerId);
          await client.query("COMMIT");
          continue;
        }
        await client.query("COMMIT");

        for (const job of jobs) {
          await processJob({
            pool,
            config,
            clock,
            providers,
            breaker,
            workerId,
            job,
          });
        }
      } catch (err) {
        await client.query("ROLLBACK").catch(() => undefined);
        log.error({ err }, "claim cycle failed");
      } finally {
        client.release();
      }
    }

    await clock.sleep(200);
  }
}

async function processJob(opts: {
  pool: pg.Pool;
  config: AppConfig;
  clock: Clock;
  providers: ReturnType<typeof createProviders>;
  breaker: CircuitBreaker;
  workerId: string;
  job: { id: string; articleId: string; attempts: number; part: "sentiment" | "summary_topics" };
}): Promise<void> {
  const { pool, config, clock, providers, breaker, workerId, job } = opts;
  const art = await pool.query<{ headline: string | null; body: string | null }>(
    `SELECT headline, body FROM articles WHERE id = $1`,
    [job.articleId],
  );
  const row = art.rows[0];
  if (!row) return;
  const text = [row.headline, row.body].filter(Boolean).join("\n\n");
  const trust = detectInjection(text) ? "low" : "normal";
  if (trust === "low") {
    await pool.query(
      `UPDATE articles SET flags = array(SELECT DISTINCT unnest(flags || '{possible_prompt_injection}'::text[])) WHERE id = $1`,
      [job.articleId],
    );
  }

  const providerKey = job.part === "sentiment" ? "jev" : "openai";
  const dayUtc = clock.now().toISOString().slice(0, 10);
  const capDollars =
    providerKey === "jev" ? config.budget.jevDaily : config.budget.openaiDaily;
  const reserveMicro = dollarsToMicro(0.01); // small per-call hold

  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    await ensureBudgetDay(
      client,
      providerKey,
      dayUtc,
      config.budget.currency,
      dollarsToMicro(capDollars),
    );
    const remaining = await reserveBudget(client, providerKey, dayUtc, reserveMicro);
    if (remaining === null) {
      await client.query(
        `UPDATE enrichment_jobs
            SET state = 'deferred_budget', reason_code = 'budget_exhausted',
                next_attempt_at = (date_trunc('day', now() AT TIME ZONE 'UTC') + interval '1 day') AT TIME ZONE 'UTC',
                claimed_by = NULL, claim_expires_at = NULL, updated_at = now()
          WHERE id = $1 AND claimed_by = $2`,
        [job.id, workerId],
      );
      await client.query("COMMIT");
      return;
    }
    await client.query(`UPDATE enrichment_jobs SET reserved_micro = $2 WHERE id = $1`, [
      job.id,
      reserveMicro,
    ]);
    await client.query("COMMIT");
  } catch (e) {
    await client.query("ROLLBACK");
    client.release();
    throw e;
  }
  client.release();

  // Cache lookup
  const inputHash = hashInput(text, config.promptVersion);
  const cached = await pool.query<{ id: string }>(
    `SELECT id FROM enrichments
      WHERE input_hash = $1 AND part = $2 AND superseded_at IS NULL
      ORDER BY created_at DESC LIMIT 1`,
    [inputHash, job.part],
  );

  try {
    let costMicro = 0;
    if (job.part === "sentiment") {
      let result;
      if (cached.rows[0]) {
        // Re-use would need copying derived values — for simplicity call mock/provider;
        // cache hit path: still call but mark origin if we had stored raw — skip, call provider
      }
      result = await providers.classifySentiment(text, row.headline);
      const priceIn = config.jev.priceInPerMtok ?? 0;
      const priceOut = config.jev.priceOutPerMtok ?? 0;
      costMicro =
        result.origin === "mock"
          ? 0
          : estimateCostMicro(
              result.usage.inputTokens ?? 0,
              result.usage.outputTokens ?? 0,
              priceIn,
              priceOut,
            );
      const c = await pool.connect();
      try {
        await c.query("BEGIN");
        await finishSentiment(c, {
          jobId: job.id,
          articleId: job.articleId,
          workerId,
          promptVersion: config.promptVersion,
          result,
          inputHash,
          truncated: false,
          trust,
          costMicro,
          reservedMicro: reserveMicro,
          providerBudgetKey: providerKey,
          dayUtc,
        });
        await c.query("COMMIT");
        breaker.onSuccess();
      } catch (e) {
        await c.query("ROLLBACK");
        throw e;
      } finally {
        c.release();
      }
    } else {
      const result = await providers.summariseAndTag(text, row.headline);
      const priceIn = config.openai.priceInPerMtok ?? 0;
      const priceOut = config.openai.priceOutPerMtok ?? 0;
      costMicro =
        result.origin === "mock"
          ? 0
          : estimateCostMicro(
              result.usage.inputTokens ?? 0,
              result.usage.outputTokens ?? 0,
              priceIn,
              priceOut,
            );
      const c = await pool.connect();
      try {
        await c.query("BEGIN");
        await finishSummaryTopics(c, {
          jobId: job.id,
          articleId: job.articleId,
          workerId,
          promptVersion: config.promptVersion,
          result,
          inputHash,
          truncated: false,
          trust,
          costMicro,
          reservedMicro: reserveMicro,
          providerBudgetKey: providerKey,
          dayUtc,
        });
        await c.query("COMMIT");
        breaker.onSuccess();
      } catch (e) {
        await c.query("ROLLBACK");
        throw e;
      } finally {
        c.release();
      }
    }
    await pool.query(`SELECT worker_set_flag($1, $2)`, [
      `breaker.${breaker.name}`,
      breaker.snapshot(),
    ]);
  } catch (err) {
    breaker.onFailure(clock.now().getTime());
    const cls = classifyProviderError(err);
    const maxA = maxAttemptsFor(cls, config.maxAttempts);
    const c = await pool.connect();
    try {
      await c.query("BEGIN");
      await releaseBudget(c, providerKey, dayUtc, reserveMicro);
      if (job.attempts >= maxA || cls === "permanent") {
        await c.query(
          `UPDATE enrichment_jobs
              SET state = 'dead', reason_code = $3, last_error = $4,
                  reserved_micro = 0, claimed_by = NULL, claim_expires_at = NULL, updated_at = now()
            WHERE id = $1 AND claimed_by = $2`,
          [
            job.id,
            workerId,
            cls === "invalid_output" ? "invalid_output" : "permanent_failure",
            (err instanceof Error ? err.message : String(err)).slice(0, 500),
          ],
        );
      } else {
        const delay = nextDelayMs(job.attempts, clock);
        await c.query(
          `UPDATE enrichment_jobs
              SET state = 'failed_retryable',
                  invalid_attempts = invalid_attempts + CASE WHEN $5 THEN 1 ELSE 0 END,
                  next_attempt_at = now() + ($3 || ' milliseconds')::interval,
                  reserved_micro = 0, claimed_by = NULL, claim_expires_at = NULL,
                  last_error = $4, updated_at = now()
            WHERE id = $1 AND claimed_by = $2`,
          [
            job.id,
            workerId,
            String(delay),
            (err instanceof Error ? err.message : String(err)).slice(0, 500),
            cls === "invalid_output",
          ],
        );
      }
      await c.query("COMMIT");
    } catch (e) {
      await c.query("ROLLBACK");
      log.error({ err: e }, "failure handling failed");
    } finally {
      c.release();
    }
    await pool.query(`SELECT worker_set_flag($1, $2)`, [
      `breaker.${breaker.name}`,
      breaker.snapshot(),
    ]);
  }
}

