    ports:
      - "127.0.0.1:5432:5432"

import type pg from "pg";

export type ClaimedJob = {
  id: string;
  articleId: string;
  attempts: number;
  part: "sentiment" | "summary_topics";
};

export async function claimJobs(
  db: pg.PoolClient,
  part: "sentiment" | "summary_topics",
  workerId: string,
  limit: number,
  visibilitySeconds = 180,
): Promise<ClaimedJob[]> {
  const res = await db.query<{
    id: string;
    article_id: string;
    attempts: number;
    part: string;
  }>(
    `WITH c AS (
       SELECT id FROM enrichment_jobs
        WHERE part = $1
          AND state IN ('queued','failed_retryable','deferred_budget')
          AND next_attempt_at <= now()
        ORDER BY next_attempt_at, id
        LIMIT $2
        FOR UPDATE SKIP LOCKED
     )
     UPDATE enrichment_jobs j
        SET state = 'running',
            claimed_by = $3,
            claimed_at = now(),
            claim_expires_at = now() + ($4::text || ' seconds')::interval,
            attempts = attempts + 1,
            updated_at = now()
       FROM c WHERE j.id = c.id
     RETURNING j.id, j.article_id, j.attempts, j.part`,
    [part, limit, workerId, String(visibilitySeconds)],
  );
  return res.rows.map((r) => ({
    id: String(r.id),
    articleId: String(r.article_id),
    attempts: r.attempts,
    part: r.part as "sentiment" | "summary_topics",
  }));
}

/** Release a claim without counting as a real attempt (breaker pre-check path). */
export async function releaseUnchanged(
  db: pg.PoolClient,
  jobId: string,
  workerId: string,
): Promise<void> {
  await db.query(
    `UPDATE enrichment_jobs
        SET state = 'queued',
            claimed_by = NULL,
            claimed_at = NULL,
            claim_expires_at = NULL,
            attempts = greatest(0, attempts - 1),
            updated_at = now()
      WHERE id = $1 AND claimed_by = $2 AND state = 'running'`,
    [jobId, workerId],
  );
}
export type BreakerState = "closed" | "open" | "half_open";

export class CircuitBreaker {
  state: BreakerState = "closed";
  failures = 0;
  openedAt = 0;
  constructor(
    readonly name: string,
    readonly threshold = 5,
    readonly coolDownMs = 30_000,
  ) {}

  canRequest(now: number): boolean {
    if (this.state === "closed") return true;
    if (this.state === "open") {
      if (now - this.openedAt >= this.coolDownMs) {
        this.state = "half_open";
        return true;
      }
      return false;
    }
    // half_open: allow single probe
    return true;
  }

  onSuccess(): void {
    this.failures = 0;
    this.state = "closed";
  }

  onFailure(now: number): void {
    this.failures++;
    if (this.state === "half_open" || this.failures >= this.threshold) {
      this.state = "open";
      this.openedAt = now;
      this.failures = 0;
    }
  }

  snapshot(): string {
    return JSON.stringify({ state: this.state, failures: this.failures, openedAt: this.openedAt });
  }
}
import type { Clock } from "../lib/clock";
import type { FailureClass } from "./classify";

export function maxAttemptsFor(cls: FailureClass, configuredMax: number): number {
  if (cls === "permanent") return 1;
  if (cls === "invalid_output") return 2;
  return configuredMax;
}

export function nextDelayMs(attempt: number, clock: Clock): number {
  const base = Math.min(60_000, 1000 * 2 ** Math.max(0, attempt - 1));
  const jitter = Math.floor((clock.now().getTime() % 500) * (base / 500));
  return base + (jitter % Math.max(1, Math.floor(base * 0.2)));
}
export type FailureClass = "transient" | "invalid_output" | "permanent";

export function classifyProviderError(err: unknown): FailureClass {
  if (!(err instanceof Error)) return "transient";
  const status = (err as Error & { status?: number }).status;
  const msg = err.message.toLowerCase();
  if (msg.includes("invalid output") || msg.includes("schema") || msg.includes("unknown_topic")) {
    return "invalid_output";
  }
  if (status === 401 || status === 403 || status === 400) return "permanent";
  if (status && status >= 500) return "transient";
  if (msg.includes("abort") || msg.includes("timeout") || msg.includes("econn")) return "transient";
  if (status && status >= 400 && status < 500) return "permanent";
  return "transient";
}
