import type { AstNode } from "./parse";
import { classifyLeaf, escapeIlike, normaliseLeafTerm } from "./leaf";

export type CompiledQuery = {
  sql: string | null;
  params: unknown[];
};

/** Compile AST to a SQL boolean fragment with numbered parameters starting at startIndex. */
export function compileAst(ast: AstNode | null, startIndex = 1): CompiledQuery {
  if (!ast) return { sql: null, params: [] };
  const params: unknown[] = [];
  let next = startIndex;

  function push(value: unknown): number {
    params.push(value);
    const i = next;
    next++;
    return i;
  }

  function compile(node: AstNode): string {
    switch (node.type) {
      case "and":
        return `(${compile(node.left)}) AND (${compile(node.right)})`;
      case "or":
        return `(${compile(node.left)}) OR (${compile(node.right)})`;
      case "and_not":
        return `(${compile(node.left)}) AND NOT (${compile(node.right)})`;
      case "term": {
        const kind = classifyLeaf(node.value);
        const norm = normaliseLeafTerm(node.value);
        if (kind === "substring") {
          const idx = push(`%${escapeIlike(norm)}%`);
          return `a.search_text ILIKE $${idx} ESCAPE '\\'`;
        }
        if (node.phrase) {
          const idx = push(norm);
          return `a.search_vector @@ phraseto_tsquery('simple', $${idx})`;
        }
        if (node.wildcard) {
          // Only letters/numbers already validated by parser for prefix
          const safe = norm.replace(/[^\p{L}\p{N}]+/gu, "");
          const idx = push(`${safe}:*`);
          return `a.search_vector @@ to_tsquery('simple', $${idx})`;
        }
        const idx = push(norm);
        return `a.search_vector @@ plainto_tsquery('simple', $${idx})`;
      }
    }
  }

  return { sql: compile(ast), params };
}
import { normaliseText } from "../normalise";

export type LeafKind = "fts" | "substring";

/** Choose FTS vs substring by script content of the term. */
export function classifyLeaf(term: string): LeafKind {
  // Han, Hiragana, Katakana, Arabic blocks → substring
  if (/[\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF\uFB50-\uFDFF\uFE70-\uFEFF]/.test(term)) {
    return "substring";
  }
  if (/[\u3040-\u30FF\u3400-\u9FFF\uF900-\uFAFF]/.test(term)) {
    return "substring";
  }
  return "fts";
}

export function escapeIlike(term: string): string {
  return term.replace(/\\/g, "\\\\").replace(/%/g, "\\%").replace(/_/g, "\\_");
}

export function normaliseLeafTerm(term: string): string {
  return normaliseText(term);
}
